-- Explicit demo fixture: 36 completed yesterday; 18 waiting today. Re-running replaces this batch.
-- Existing real student records and service configuration are preserved.
USE campus_queue;
SET time_zone = '+05:30';
START TRANSACTION;
SELECT service_id FROM services WHERE service_name IN ('General Inquiries','Fee Payment','Document Verification') ORDER BY service_id FOR UPDATE;
DELETE q FROM queue q JOIN students s ON s.student_id=q.student_id WHERE s.student_name LIKE '[DEMO] %' AND (s.email LIKE 'demo-queue-2026-10-07-%@example.invalid' OR s.email LIKE 'presentation-demo-2026-10-08-%@example.invalid');
DELETE b FROM bookings b JOIN students s ON s.student_id=b.student_id WHERE s.student_name LIKE '[DEMO] %' AND s.email LIKE 'demo-queue-2026-10-07-%@example.invalid' AND b.booking_date='2026-10-07';
SET @service = (SELECT service_id FROM services WHERE service_name='General Inquiries' ORDER BY service_id LIMIT 1);
INSERT INTO students(student_name,email,password) VALUES ('[DEMO] Aarav History S1','presentation-demo-2026-10-08-1-history-1@example.invalid','pbkdf2$210000$RrZpVGbGSNS9GwME/MS/PA==$ODeCo+PWx1gDf8nDsczQ41fFDo84vj2dcuqYz8ug2Ks=') ON DUPLICATE KEY UPDATE student_name=VALUES(student_name);
SET @student=(SELECT student_id FROM students WHERE email='presentation-demo-2026-10-08-1-history-1@example.invalid');
SET @token=(SELECT COALESCE(MAX(token_number),0)+1 FROM queue WHERE service_id=@service);
SET @ordering=(SELECT COALESCE(MAX(r.queue_order),0)+1 FROM queue_reservations r JOIN queue q ON q.queue_id=r.queue_id WHERE q.service_id=@service AND r.visit_date='2026-10-07');
