SELECT sv.service_name,q.status,r.visit_date,COUNT(*) AS demo_entries,ROUND(AVG(q.processing_seconds)/60,3) AS measured_minutes FROM queue q JOIN students st ON st.student_id=q.student_id JOIN services sv ON sv.service_id=q.service_id JOIN queue_reservations r ON r.queue_id=q.queue_id WHERE st.email LIKE 'presentation-demo-2026-10-08-%@example.invalid' GROUP BY sv.service_name,q.status,r.visit_date ORDER BY sv.service_name,r.visit_date;
